  'pol.stat.pm': { en: `Federal Council salary + CHF 12,000 with no tax`, nl: `Loon van de Bondsraad + CHF 12.000 zonder belasting`, fr: `Traitement du Conseil fédéral + 12 000 CHF sans impôt` },
  'pol.stat.minister': { en: `Salary set by law`, nl: `Loon vastgelegd bij wet`, fr: `Traitement fixé par la loi` },
  'pol.stat.mp': { en: `2023 average taxed pay, without the untaxed money for expenses`, nl: `Gemiddeld belast loon 2023, zonder het onbelaste geld voor onkosten`, fr: `Revenu imposé moyen 2023, sans l'argent pour frais non imposé` },
  'pol.stat.senator': { en: `2023 average taxed pay, without the untaxed money for expenses`, nl: `Gemiddeld belast loon 2023, zonder het onbelaste geld voor onkosten`, fr: `Revenu imposé moyen 2023, sans l'argent pour frais non imposé` },
  polAllow: { en: `Tax-free allowances`, nl: `Belastingvrije vergoedingen`, fr: `Indemnités exonérées` },
  'polTitle.gov': { en: `Other public offices, gross pay`, nl: `Andere openbare ambten, brutoloon`, fr: `Autres fonctions publiques, rémunération brute` },
  'polTitle.corp': { en: `Heads of federal companies, gross pay`, nl: `Topmensen van federale bedrijven, brutoloon`, fr: `Dirigeants d'entreprises fédérales, rémunération brute` },
  'polNote.pm': {
    en: `AHV/IV/EO and unemployment contributions, no pension fund, taxed like a salary in your town and household. The CHF 42,000 for expenses is not taxed and is added to the net. The head shows which employee salary would leave the same net pay; the dot shows what they really earn before tax.`,
    nl: `AHV/IV/EO- en werkloosheidsbijdragen, geen pensioenfonds, belast als loon in jouw gemeente en gezin. De CHF 42.000 voor onkosten wordt niet belast en komt bij het netto. Het hoofdje toont welk werknemersloon hetzelfde netto zou opleveren; het bolletje toont wat ze echt verdienen voor belastingen.`,
    fr: `Cotisations AVS/AI/APG et chômage, pas de caisse de pension, imposé comme un salaire dans votre commune et votre foyer. Les 42 000 CHF pour frais ne sont pas imposés et s'ajoutent au net. La tête montre quel salaire d'un salarié donnerait le même net ; le point montre ce qu'ils gagnent vraiment avant impôts.`,
  },
  'polNote.minister': {
    en: `AHV/IV/EO and unemployment contributions, no pension fund, taxed like a salary in your town and household. The CHF 30,000 for expenses is not taxed and is added to the net. The head shows which employee salary would leave the same net pay; the dot shows what they really earn before tax.`,
    nl: `AHV/IV/EO- en werkloosheidsbijdragen, geen pensioenfonds, belast als loon in jouw gemeente en gezin. De CHF 30.000 voor onkosten wordt niet belast en komt bij het netto. Het hoofdje toont welk werknemersloon hetzelfde netto zou opleveren; het bolletje toont wat ze echt verdienen voor belastingen.`,
    fr: `Cotisations AVS/AI/APG et chômage, pas de caisse de pension, imposé comme un salaire dans votre commune et votre foyer. Les 30 000 CHF pour frais ne sont pas imposés et s'ajoutent au net. La tête montre quel salaire d'un salarié donnerait le même net ; le point montre ce qu'ils gagnent vraiment avant impôts.`,
  },
  'polNote.mp': {
    en: `Average 2023 pay of a member of the National Council: CHF 76,138 taxed (a CHF 26,000 base, CHF 440 per day of sitting, and the federal payment for their pension) and CHF 61,782 for expenses with no tax, added to the net. AHV/IV/EO is paid on the taxed part; the member pays a quarter of the pension payment. The head shows which employee salary would leave the same net pay.`,
    nl: `Gemiddeld loon 2023 van een lid van de Nationale Raad: CHF 76.138 belast (een basis van CHF 26.000, CHF 440 per vergaderdag en de federale storting voor hun pensioen) en CHF 61.782 voor onkosten zonder belasting, bij het netto geteld. Op het belaste deel wordt AHV/IV/EO betaald; het lid betaalt een kwart van de pensioenstorting. Het hoofdje toont welk werknemersloon hetzelfde netto zou opleveren.`,
    fr: `Rémunération moyenne 2023 d'un conseiller national : 76 138 CHF imposés (une base de 26 000 CHF, 440 CHF par jour de séance et le versement fédéral pour leur retraite) et 61 782 CHF pour frais sans impôt, ajoutés au net. L'AVS/AI/APG est payée sur la partie imposée ; le membre paie un quart du versement retraite. La tête montre quel salaire d'un salarié donnerait le même net.`,
  },
  'polNote.senator': {
    en: `Average 2023 pay of a member of the Council of States, who sit on more committees: CHF 89,023 taxed and CHF 66,584 for expenses with no tax, added to the net. Same rules as the National Council. The head shows which employee salary would leave the same net pay.`,
    nl: `Gemiddeld loon 2023 van een lid van de Kantonsraad, dat in meer commissies zit: CHF 89.023 belast en CHF 66.584 voor onkosten zonder belasting, bij het netto geteld. Dezelfde regels als de Nationale Raad. Het hoofdje toont welk werknemersloon hetzelfde netto zou opleveren.`,
    fr: `Rémunération moyenne 2023 d'un conseiller aux États, qui siège dans plus de commissions : 89 023 CHF imposés et 66 584 CHF pour frais sans impôt, ajoutés au net. Mêmes règles qu'au Conseil national. La tête montre quel salaire d'un salarié donnerait le même net.`,
  },
  'polTipNote.pm': { en: `Yearly salary. The President gets CHF 12,000 more, with no tax.`, nl: `Jaarloon. De president krijgt CHF 12.000 extra, zonder belasting.`, fr: `Traitement annuel. Le président reçoit 12 000 CHF de plus, sans impôt.` },
  'polTipNote.minister': { en: `Yearly salary, going up with prices like federal staff pay.`, nl: `Jaarloon, stijgend met de prijzen zoals het loon van het federale personeel.`, fr: `Traitement annuel, qui augmente avec les prix comme celui du personnel fédéral.` },
  'polTipNote.mp': { en: `Average taxed pay in 2023. It varies a lot from one member to another, because they are paid per day of sitting.`, nl: `Gemiddeld belast loon in 2023. Het verschilt sterk van lid tot lid, omdat ze per vergaderdag betaald worden.`, fr: `Revenu imposé moyen en 2023. Il varie beaucoup d'un membre à l'autre, car ils sont payés par jour de séance.` },
  'polTipNote.senator': { en: `Average taxed pay in 2023. It varies a lot from one member to another, because they are paid per day of sitting.`, nl: `Gemiddeld belast loon in 2023. Het verschilt sterk van lid tot lid, omdat ze per vergaderdag betaald worden.`, fr: `Revenu imposé moyen en 2023. Il varie beaucoup d'un membre à l'autre, car ils sont payés par jour de séance.` },
  polNote: {
    en: links => `Point at a name to see details, click it to zoom in. Yearly pay before tax, placed on the chart as yearly ÷ months paid. Federal Councillors and members of parliament are placed where an employee would take home the same net pay, with your town and household. Parliament figures are 2023 averages (${links}).`,
    nl: links => `Wijs een naam aan voor details, klik om in te zoomen. Jaarloon voor belastingen, op de grafiek geplaatst als jaarbedrag ÷ betaalde maanden. Bondsraadsleden en parlementsleden staan waar een werknemer hetzelfde netto zou overhouden, met jouw gemeente en gezin. De cijfers van het parlement zijn gemiddelden van 2023 (${links}).`,
    fr: links => `Pointez un nom pour voir les détails, cliquez pour zoomer. Rémunération annuelle brute, placée sur le graphique en montant annuel ÷ mois payés. Les conseillers fédéraux et les parlementaires sont placés là où un salarié toucherait le même net, avec votre commune et votre foyer. Les chiffres du Parlement sont des moyennes 2023 (${links}).`,
  },
  'src.pol.pm': { en: `Federal act on the pay of magistrates`, nl: `Federale wet op de bezoldiging van magistraten`, fr: `Loi fédérale sur le traitement des magistrats` },
  'src.pol.minister': { en: `Federal act on the pay of magistrates`, nl: `Federale wet op de bezoldiging van magistraten`, fr: `Loi fédérale sur le traitement des magistrats` },
