  // Chart notes
  bracketTop: { en: `federal tax flat at 11.5%`, nl: `federale belasting vlak op 11,5%`, fr: `impôt fédéral fixe à 11,5%` },
  chartTitle: { en: `Tax and buying power at each salary level`, nl: `Belasting en koopkracht per loonniveau`, fr: `Prélèvements et pouvoir d'achat à chaque niveau de salaire` },
  chartAria: { en: `Tax rate per salary chart`, nl: `Grafiek van het belastingtarief per loon`, fr: `Graphique du taux de prélèvement par salaire` },
  trapTitle: { en: (a, b) => `Why the jump between ${a} and ${b}?`, nl: (a, b) => `Waarom de sprong tussen ${a} en ${b}?`, fr: (a, b) => `Pourquoi le saut entre ${a} et ${b} ?` },
  trapBody: {
    en: (a, b, coord, contrib) => `At ${a} you join the pension fund (BVG), all at once. Contributions start on a minimum amount of ${coord} (the "coordinated salary"): about ${contrib} a year from you and the same from your employer. Up to ${b} this minimum applies; after that, contributions grow with your pay. Many cantons also give a tax deduction for modest incomes that disappears in this range.`,
    nl: (a, b, coord, contrib) => `Bij ${a} kom je in één keer in het pensioenfonds (BVG). De bijdragen beginnen op een minimumbedrag van ${coord} (het "gecoördineerd loon"): ongeveer ${contrib} per jaar van jou en evenveel van je werkgever. Tot ${b} geldt dat minimum; daarna groeien de bijdragen mee met je loon. Veel kantons geven ook een belastingaftrek voor bescheiden inkomens die in deze zone verdwijnt.`,
    fr: (a, b, coord, contrib) => `À ${a}, vous entrez d'un coup dans la caisse de pension (LPP). Les cotisations démarrent sur un montant minimum de ${coord} (le « salaire coordonné ») : environ ${contrib} par an pour vous et autant pour votre employeur. Jusqu'à ${b}, ce minimum s'applique ; ensuite, les cotisations suivent votre salaire. Beaucoup de cantons donnent aussi une déduction d'impôt pour revenus modestes qui disparaît dans cette zone.`,
  },
  topTitle: { en: top => `Why the drop at ${top}?`, nl: top => `Waarom de daling bij ${top}?`, fr: top => `Pourquoi la baisse à ${top} ?` },
  topBody: {
    en: (top, cap) => `From ${top}, your federal taxable income goes above ${cap}. Above that, the federal tax no longer goes up with income: it is simply 11.5% of all taxable income. So the next franc is taxed less than the one before. Cantonal tax stays at its highest rate.`,
    nl: (top, cap) => `Vanaf ${top} komt je federaal belastbaar inkomen boven ${cap}. Daarboven stijgt de federale belasting niet meer mee met het inkomen: ze is gewoon 11,5% van het hele belastbare inkomen. De volgende frank wordt dus lager belast dan de vorige. De kantonnale belasting blijft op haar hoogste tarief.`,
    fr: (top, cap) => `À partir de ${top}, votre revenu imposable fédéral dépasse ${cap}. Au-delà, l'impôt fédéral n'augmente plus avec le revenu : il vaut simplement 11,5% de tout le revenu imposable. Le franc suivant est donc moins taxé que le précédent. L'impôt cantonal reste à son taux le plus haut.`,
  },

